import{_ as a,C as n,o as r,c as i,a2 as t,E as o}from"./chunks/framework.9yf7n3zg.js";const h="/guide/media/lenses-style.webp",d="/guide/media/lenses-rhythm.webp",c="/guide/media/lenses-settings.webp",l="/guide/media/lenses-dialogue.webp",g="/guide/media/lenses-accents.webp",v=JSON.parse('{"title":"Lenses and style checks","description":"","frontmatter":{},"headers":[],"relativePath":"guide/lenses.md","filePath":"guide/lenses.md","lastUpdated":1792685126000}'),u={name:"guide/lenses.md"};function p(m,e,w,f,y,k){const s=n("Clip");return r(),i("div",null,[e[0]||(e[0]=t('<h1 id="lenses-and-style-checks" tabindex="-1">Lenses and style checks <a class="header-anchor" href="#lenses-and-style-checks" aria-label="Permalink to &quot;Lenses and style checks&quot;">​</a></h1><p>A lens is a reading pass laid over the <a href="/guide/guide/manuscript">manuscript</a> page. It tints the words it is about (the length of each sentence, a tired phrase, who is speaking, a phrase you reached for twice) so you can see one kind of thing across the whole book. Only one lens is on at a time, because five highlights cannot be read and one can. Every lens runs offline, on this computer, over the prose as it stands. A lens points; you decide. None of them changes a word of your text.</p><p><img src="'+h+'" alt="The manuscript of The Lamp at Ferrol with the Style checks lens on: a passive, a filter verb and repeated words underlined in chapter one, and What the lens found listing them in the side column" width="1130" height="732" loading="lazy"></p><h2 id="turning-a-lens-on" tabindex="-1">Turning a lens on <a class="header-anchor" href="#turning-a-lens-on" aria-label="Permalink to &quot;Turning a lens on&quot;">​</a></h2><p>On the manuscript page:</p><ul><li>Open the <strong>Lens</strong> section of the side column and click a lens. The one in force has a filled circle <code>◉</code>; the others an empty one <code>◌</code>.</li><li>Press <code>L</code> to step to the next lens, round to <strong>No lens</strong> after the last.</li><li>Click the lens name in the footer at the bottom right (<code>lens: rhythm</code>) to step to the next.</li><li>Press <code>Esc</code> with nothing selected to turn the lens off.</li></ul><p>The lenses, in the order <code>L</code> steps through them: <strong>No lens</strong>, <strong>Rhythm</strong>, <strong>Style checks</strong>, <strong>Dialogue</strong>, <strong>Echoes</strong>, <strong>Words</strong>, <strong>Accents</strong>.</p><p>With a lens on, select a paragraph (click a sentence, or use the arrow keys). <strong>What the lens found</strong>, under the lens list, then lists every mark the lens made in that paragraph, each with its note. When there is none it says <strong>Nothing found in this paragraph.</strong> Hover a tinted word on the page for the same note.</p>',8)),o(s,{name:"lenses-cycle",caption:"Pressing L on chapter one: Rhythm, Style checks, Dialogue, Echoes, Words and Accents in turn"}),e[1]||(e[1]=t('<h2 id="rhythm" tabindex="-1">Rhythm <a class="header-anchor" href="#rhythm" aria-label="Permalink to &quot;Rhythm&quot;">​</a></h2><p>The rhythm lens tints each sentence by how long it feels to a reader, cool for short and warm for long, so the rhythm of a paragraph shows at a glance. It weighs more than the word count: commas and clauses add weight, and long words add weight, so a sentence of twelve words strung on commas can sit higher than twelve plain ones. Abbreviations such as &quot;Mr.&quot; do not end a sentence. The tiers mean the same thing in every paragraph of the book.</p><p><strong>What the lens found</strong> names each sentence&#39;s band, such as <strong>rhythm tier 2 of 6</strong>.</p><p>The number of bands is <strong>Rhythm tiers</strong> in <strong>Settings › Lenses</strong>, from 4 to 6 (6 by default).</p><p><img src="'+d+'" alt="Chapter one under the Rhythm lens: short sentences in cool tints, the long sentence about the gale in a warm one" width="1130" height="832" loading="lazy"></p><p>The gutter&#39;s sentence meter, shown whatever the lens, is a plainer measure of the same thing: one tick per sentence, its width the sentence&#39;s length in words (see <a href="/guide/guide/manuscript#the-gutter">The gutter</a>).</p><h2 id="style-checks" tabindex="-1">Style checks <a class="header-anchor" href="#style-checks" aria-label="Permalink to &quot;Style checks&quot;">​</a></h2><p>The style lens points at the sentences you might look at again. Each kind of finding has its own tint and a note that says what it saw and what to try.</p><table tabindex="0"><thead><tr><th>Check</th><th>What it points at</th><th>Example note</th></tr></thead><tbody><tr><td><strong>cliché</strong></td><td>A tired phrase from Leathercase&#39;s list.</td><td>Cliché: &quot;at the end of the day&quot;. Say what you actually saw.</td></tr><tr><td><strong>passive</strong></td><td>A verb in the passive voice: &quot;was written&quot;, &quot;got hit&quot;. Names (&quot;was Helen&quot;), states (&quot;was tired&quot;) and numbers (&quot;was eleven&quot;) are left alone.</td><td>Passive voice. Who is doing this? Put them in front of the verb.</td></tr><tr><td><strong>filter</strong></td><td>A verb that puts the narrator between the reader and the scene: saw, heard, felt, noticed, realised, could see, found herself and the like. Speech, nouns (&quot;the felt&quot;), passives (&quot;was decided&quot;) and idioms (&quot;smelled of&quot;, &quot;seemed to&quot;) are left alone.</td><td>Filter verb. Render what was seen, not the seeing: &quot;she saw the door open&quot; → &quot;the door opened&quot;.</td></tr><tr><td><strong>adverb</strong></td><td>A manner adverb ending in -ly, where a stronger verb could do the work. One on a dialogue tag gets a sharper note. Words such as &quot;suddenly&quot; or &quot;obviously&quot;, which no verb replaces, are left alone, as is anything inside speech.</td><td>Adverb on a dialogue tag. Let the line itself carry the &quot;quietly&quot;.</td></tr><tr><td><strong>repetition</strong></td><td>A word that comes back within thirty words, and a run of sentences that open with the same word (three in a row; four for &quot;the&quot;, &quot;a&quot;, &quot;I&quot;, &quot;it&quot; and &quot;there&quot;).</td><td>&quot;lamp&quot; echoes a word 12 words back.</td></tr><tr><td><strong>metaphor</strong></td><td>A possible figure of speech: a concrete word on an abstract noun (&quot;velvet silence&quot;), &quot;X is a Y&quot;, or a dead metaphor. It asks; it does not judge.</td><td>Possibly figurative: … Fresh, or familiar?</td></tr><tr><td><strong>nominalization</strong></td><td>An action hiding in a noun after a light verb: &quot;made a decision&quot;, &quot;gave an explanation&quot;.</td><td>Nominalization. &quot;made … decision&quot; → &quot;decided&quot;.</td></tr><tr><td><strong>weak verb</strong></td><td>A long sentence (fourteen words or more) whose only verb is &quot;to be&quot;. Short ones such as &quot;The sky was red.&quot; are fine.</td><td>18 words carried by &quot;was&quot;. Give the sentence a verb that does something.</td></tr></tbody></table><p>The checks read English. Their word lists (clichés, filter verbs, adverbs to spare) and the grammar tagger behind them are English ones, so on a story in Portuguese or Spanish they say little that is useful.</p><h3 id="choosing-which-checks-tint" tabindex="-1">Choosing which checks tint <a class="header-anchor" href="#choosing-which-checks-tint" aria-label="Permalink to &quot;Choosing which checks tint&quot;">​</a></h3><p><strong>Settings › Lenses › Style checks</strong> has a chip for each kind: <strong>adverb</strong>, <strong>passive</strong>, <strong>filter</strong>, <strong>cliché</strong>, <strong>repetition</strong>, <strong>metaphor</strong>, <strong>nominalization</strong>, <strong>weak verb</strong>. All are on by default. Click a chip to turn that kind off; off is off everywhere. The preference is kept on this machine.</p><p><img src="'+c+'" alt="Settings › Lenses with the Rhythm tiers slider, the eight Style checks chips and Echo sensitivity" width="875" height="482" loading="lazy"></p><h3 id="not-here-keeping-one-finding-out-of-a-paragraph" tabindex="-1">Not here: keeping one finding out of a paragraph <a class="header-anchor" href="#not-here-keeping-one-finding-out-of-a-paragraph" aria-label="Permalink to &quot;Not here: keeping one finding out of a paragraph&quot;">​</a></h3><p>When a finding is a choice you made, you can tell the lens so, in your own note. Put a hidden comment in the paragraph naming the kind:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">At the end of the day, she left. %% not cliche %%</span></span></code></pre></div><p>That paragraph then shows no cliché finding. The kinds are named <code>cliche</code>, <code>passive</code>, <code>filter</code>, <code>adverb</code>, <code>repetition</code>, <code>metaphor</code>, <code>nominalization</code> and <code>weakverb</code>. You type the comment in your own app; Leathercase never writes it. Obsidian hides <code>%% … %%</code> comments, and the manuscript export leaves them out.</p><h2 id="dialogue" tabindex="-1">Dialogue <a class="header-anchor" href="#dialogue" aria-label="Permalink to &quot;Dialogue&quot;">​</a></h2><p>The dialogue lens tints speech and thought, and finds who says each line of speech. It follows a conversation from one paragraph to the next.</p><p><strong>What the lens found</strong> says, for each span, <strong>speech, Nora Vidal</strong>, <strong>thought, Nora Vidal</strong>, <strong>speech, speaker not found</strong> or <strong>thought</strong>.</p><h3 id="how-the-speaker-is-found" tabindex="-1">How the speaker is found <a class="header-anchor" href="#how-the-speaker-is-found" aria-label="Permalink to &quot;How the speaker is found&quot;">​</a></h3><p>Leathercase tries, in order:</p><ol><li><strong>A pin of yours.</strong> A hidden comment with the character&#39;s name just before a line of speech, <code>%% Tomás %% &quot;Aye.&quot;</code>, names the speaker for certain.</li><li><strong>A dialogue tag.</strong> &quot;Go,&quot; <strong>Inés said</strong>.</li><li><strong>A name in the paragraph.</strong> A character named in the same paragraph, by name or alias.</li><li><strong>Turn-taking.</strong> In a back-and-forth between two voices, an untagged line goes to the one whose turn it is.</li></ol><p>The first three are certain. Turn-taking is a guess: those lines are given a speaker too, and the <a href="#accents">accents</a> lens and the character sheet treat them as guessed. A line no rule can place reads <strong>speech, speaker not found</strong>.</p><p>The cast the lens attributes speech to is your character notes, each with its name and its <code>aliases:</code>. The story&#39;s <strong>Speakers</strong> setting narrows and orders the cast and adds names that have no note (see <a href="/guide/guide/story-settings#speakers">Story settings</a>).</p><p>The dialogue lens does not colour lines by speaker: every line of speech takes the same speech tint, every thought the thought tint, and the speaker is named in <strong>What the lens found</strong> in the side column. A character&#39;s colour, from <code>color:</code> (or <code>colour:</code>) in their note, or pinned after their name in <strong>Speakers</strong> as The Lamp at Ferrol does with <code>Nora Vidal #1f5f7a</code>, or else one from the palette in cast order, is what the <a href="#accents">accents</a> lens marks that character&#39;s words in.</p><p><img src="'+l+'" alt="Chapter five, The Reef, under the Dialogue lens: every line of speech tinted, the narration untinted, and What the lens found naming Inés Roca as the speaker of the selected paragraph" width="1130" height="700" loading="lazy"></p><h3 id="speech-and-thought-conventions" tabindex="-1">Speech and thought conventions <a class="header-anchor" href="#speech-and-thought-conventions" aria-label="Permalink to &quot;Speech and thought conventions&quot;">​</a></h3><p>The lens has to know how your story marks speech and thought. The story&#39;s <strong>Prose</strong> settings say so:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Choices</th></tr></thead><tbody><tr><td><strong>Speech is written as</strong></td><td><strong>As the prose reads</strong>, <strong>Double quotes</strong> (“Not tonight,” she said.), <strong>Single quotes</strong> (‘Not tonight,’ she said.), <strong>A dash</strong> (— Not tonight, she said.), <strong>No speech marks</strong>.</td></tr><tr><td><strong>Thoughts are written as</strong></td><td><strong>As the prose reads</strong>, <strong>An italic paragraph</strong> (<em>He is up there. He has to be.</em>), <strong>Italics anywhere</strong>, <strong>Single quotes</strong> (‘He is up there,’ she thought.), <strong>Not marked</strong>.</td></tr></tbody></table><p><strong>As the prose reads</strong>, the default, lets Leathercase tell the convention from your paragraphs. Under it, a word or two in italics inside a sentence is emphasis, never a thought; a whole italic paragraph, or an italic sentence of three words or more, or one followed by &quot;she thought&quot; or &quot;he wondered&quot;, is a thought. A dash at the start of a paragraph opens speech, and each further dash in it switches between narration and speech, as Portuguese and French prose do. Straight single quotes are told from apostrophes by where they sit.</p><p>The settings page shows which convention it read in your prose, and in how many paragraphs, with one of your own sentences re-marked in each other convention. See <a href="/guide/guide/story-settings#prose">Story settings</a>.</p><h2 id="echoes" tabindex="-1">Echoes <a class="header-anchor" href="#echoes" aria-label="Permalink to &quot;Echoes&quot;">​</a></h2><p>The echoes lens hears what is hard to hear from inside a draft: a phrase you reached for in more than one scene, and a sentence written again in slightly different words a few scenes later. It reads the whole story, scene by scene.</p><p><strong>What the lens found</strong> says <strong>&quot;There was salt on the wind&quot; recurs in 2 scenes</strong> for a phrase, or <strong>echoes a sentence 3 scenes away</strong> for a near-repeat.</p><p>Three things are never an echo:</p><ul><li>A character&#39;s name, or any word of a name or an alias.</li><li>A phrase you quoted in a thread. A motif you kept on purpose is yours, not a finding.</li><li>Phrases too common to mean anything.</li></ul><p>How close two passages must be before they are marked is <strong>Echo sensitivity</strong> in <strong>Settings › Lenses</strong>: <strong>Low</strong>, <strong>Medium</strong> (the default) or <strong>High</strong>. The same finder runs in the <a href="/guide/guide/threads">threads</a> view.</p><h2 id="words" tabindex="-1">Words <a class="header-anchor" href="#words" aria-label="Permalink to &quot;Words&quot;">​</a></h2><p>The words lens marks your own word lists: the words you overuse, the words you never want to use, the stage directions you lean on. Each list has its colour, and a marked word shows in it. <strong>What the lens found</strong> says the list and the word, such as <strong>Never use: suddenly</strong>.</p><p>The lists live in <code>WordLists.md</code> in the story&#39;s suite folder. With no list yet the lens says: <strong>No word list yet. Put one in WordLists.md in your suite folder: a heading per category, the words under it.</strong></p><p>From the page you can:</p><ul><li><strong>Put a word in a list.</strong> With the words lens on, drag across a word or a short phrase (up to four words). Under the findings, <strong>Put “felt” in a word list</strong> appears with a <strong>List</strong> field (it suggests your lists, and <strong>Never use</strong> as a start) and <strong>Add</strong>. Type a list name that does not exist and the list is made.</li><li><strong>Take a word out.</strong> Select a paragraph where the lens marked a word, and click <strong>Take “felt” out of the word lists</strong> under the findings.</li></ul><p>Both write <code>WordLists.md</code>, never your chapter. The lists can also be edited on the story&#39;s settings page, and by hand. The file&#39;s format is on the <a href="/guide/guide/comments#word-lists">Comments and word lists</a> page.</p>',44)),o(s,{name:"lenses-words-add",caption:"With the Words lens on, dragging across knew in chapter one and putting it in a new list, Filtering"}),e[2]||(e[2]=t(`<h2 id="accents" tabindex="-1">Accents <a class="header-anchor" href="#accents" aria-label="Permalink to &quot;Accents&quot;">​</a></h2><p>The accents lens marks how each character speaks: the words that are theirs, and the words they never say. Each mark is in the character&#39;s colour: the <code>color:</code> in their note, the colour pinned after their name in the story&#39;s <strong>Speakers</strong> setting, or one from the palette (see <a href="#dialogue">Dialogue</a>).</p><ul><li>A word a character uses, in their own certain speech, is marked: <strong>Nora Vidal&#39;s word: “lamp”</strong>.</li><li>A word a character never says, found in their certain speech, is a slip: <strong>Nora Vidal never says “salvage”</strong>.</li><li>In a line only guessed to be theirs by turn-taking, the mark is dotted and never counts as a slip: <strong>Nora Vidal&#39;s word: “tower”, in a line only guessed to be theirs</strong>.</li></ul><p>Words in the narration, or in another character&#39;s speech, are not marked.</p><p>A character&#39;s words come from two places, joined:</p><table tabindex="0"><thead><tr><th>Where</th><th>What</th></tr></thead><tbody><tr><td>The character&#39;s note</td><td><code>accent:</code> and <code>accent-never:</code> in its front matter, as Nora Vidal&#39;s note in the sample has <code>accent: [tower, lamp, watch]</code> and <code>accent-never: [salvage]</code>. Yours to edit, in your app.</td></tr><tr><td><code>Accents.md</code></td><td>In the story&#39;s suite folder. Kept by Leathercase from what you tell it on the page or on the character&#39;s <strong>Voice</strong> tab.</td></tr></tbody></table><p><code>Accents.md</code> reads like this, a heading per character and two lines under it:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Nora Vidal</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">says: aye, the lamp</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">never: okay, gonna</span></span></code></pre></div><p>A word sits in one list per character. Saying a character never says a word they use moves it across.</p><p>With no accents for anyone yet the lens says: <strong>No accents yet. Give a character the words they use or never say on the Voice tab of their sheet, in Characters, or select a word in their speech.</strong> See <a href="/guide/guide/characters">Characters</a>.</p><p>From the page, with the accents lens on, drag across a word or short phrase in a line of speech. <strong>Give “aye” to a character</strong> appears: <strong>Who</strong> offers the cast, with the paragraph&#39;s certain speaker first, and two buttons, <strong>Says “aye”</strong> and <strong>Never says “aye”</strong>. Either writes <code>Accents.md</code>.</p><p>The character sheet&#39;s <strong>Voice</strong> tab counts the same marks (marks in certain speech, more in guessed lines, slips) and has <strong>Open the accents lens</strong>, which opens this page with the lens on.</p><p><img src="`+g+'" alt="Chapter three, The Guild Hall, under the Accents lens: Nora&#39;s word lamp underlined in her colour inside her speech, and What the lens found reading Nora Vidal&#39;s word: “lamp”" width="1130" height="810" loading="lazy"></p><h2 id="what-the-lenses-never-do" tabindex="-1">What the lenses never do <a class="header-anchor" href="#what-the-lenses-never-do" aria-label="Permalink to &quot;What the lenses never do&quot;">​</a></h2><ul><li>They never change your text, and never write into your notes.</li><li>They never send your text anywhere: every lens runs on this computer, with no model and no network.</li><li>They never read a screenplay: a Fountain story shows as a script with no lens over it.</li></ul><p>The only files a lens writes are Leathercase&#39;s own <code>WordLists.md</code> and <code>Accents.md</code>, and only when you add or take out a word.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/guide/guide/manuscript">Manuscript</a></li><li><a href="/guide/guide/comments">Comments and word lists</a></li><li><a href="/guide/guide/story-settings">Story settings</a></li><li><a href="/guide/guide/characters">Characters</a></li><li><a href="/guide/reference/settings">Settings</a></li><li><a href="/guide/reference/front-matter">Front matter</a></li></ul>',18))])}const q=a(u,[["render",p]]);export{v as __pageData,q as default};
